const TAU = 6.2831853071795864;
fn wrapP(p: f32) -> f32 { return p - TAU * floor(p / TAU); }
fn sstep(a: f32, b: f32, x: f32) -> f32 { let t = clamp((x - a) / (b - a), 0.0, 1.0); return t * t * (3.0 - 2.0 * t); }
fn swell(ph: f32, s: f32) -> f32 {
