fn seaAt(k: i32) -> vec2f { let v = P.sea[k / 2]; if ((k & 1) == 0) { return v.xy; } return v.zw; }
// (deepFactor, 43-render-objects.js: past the world's ends the open ocean; else its own sea's middle - the sea holding x, or the nearest)
fn deepF(x: f32) -> f32 {
