  for (var k = 0; k < 8; k++) { if (k >= P.nsea) { break; } let m = seaAt(k);   // (at most 8 seas: P.sea's room)
    let d = max(abs(x - m.x) - m.y, 0.0); if (d < sd) { sd = d; sk = k; } }
  if (P.nsea == 0) { return 0.0; }
