fn whAt(c: i32) -> f32 { return wh[clamp(c - P.winLo, 0, P.winN - 1)]; }
// the surface at the table's column i, exact (surfaceY0: the level less the swell and the stepped waves, times the shelter)
fn exact(i: i32) -> f32 {
  let di = f32(i) / P.sv;
  let x = P.x0 + di;
