  let p4 = wrapP(P.ph[0].w + 0.11 * di);
  let p5 = wrapP(P.ph[1].x + 0.0062 * di);
  let q1 = wrapP(P.ph[1].y + 0.0019 * di);
  let q2 = wrapP(P.ph[1].z + 0.0047 * di);
