  let st = P.storm;
  let amb = (1.0 + 0.1 * deepF(x)) * (A * (3.0 * swell(p1, s * 0.8) + 1.7 * swell(p2, s) + 0.8 * swell(p3, s * 0.9))
    + 0.35 * sin(p4) * (1.0 + st * 3.0) + st * st * 9.0 * swell(p5, s * 0.6));
