}
// one invocation a column of the view (c = o - 3): its row on the screen (PY) and its height in the world
@compute @workgroup_size(64) fn surf(@builtin(global_invocation_id) g: vec3u) {
  let o = i32(g.x); if (o >= P.nOut) { return; }
