  var y = 0.0;
  if ((i & 3) == 0) { y = exact(i); } else { let a = i - (i & 3); let ya = exact(a); let yb = exact(a + 4); y = ya + (yb - ya) / 4.0 * f32(i - a); }
  surfOut[o] = vec2f(floor((y - P.waterY) * P.sv + P.kpy + 0.5), y);
