// ---- THE FOAM ON THE WATER (drawFoamBits): a bit of the foam table an instance (items: 2 each - its column on the screen (PX), size, k, age (life / max); its
// seed), by FOAM_L's rules. A small one (k 1): a line of 1-3 pixels on the surface, white then pale. A big ship's (k > 1): a flat clump of PB blocks
// floating on the surface, as wide as its size, breaking into pieces with gaps as it ages - the ends first, lower as it settles, a wet underside on the
// taller pieces while young; its pieces' picks from the whole-number hash (wLat, its seed's bits and the piece). wk: [0] PB; [1..4] FOAM_PAL (premultiplied)
fn foamW(s: f32) -> f32 { return max(D.wk[0].x, floor(s * 4.5 * D.ds.z / D.wk[0].x + 0.5) * D.wk[0].x); }
fn foamHMax(nb: f32, t: f32) -> f32 { return max(1.0, floor(nb * 0.4 * (1.0 - 0.6 * t) + 0.5)); }
@vertex fn vsFoam(@builtin(vertex_index) v: u32, @builtin(instance_index) n: u32) -> VO {
  let a = items[n * 2u]; let PB = D.wk[0].x; let c = a.x;
