    let w = foamW(a.y); let nb = max(1.0, floor(w / PB + 0.5)); let bx = floor((c - w / 2.0) / PB) * PB; let sy = floor(surfRow(c) / PB) * PB;
    bb = vec4f(bx, sy - (foamHMax(nb, a.w) * 1.2 + 1.0) * PB, bx + nb * PB, sy + 2.0 * PB);
  }
