  var o: VO; o.p = vec4f(d.x / D.tgt.x * 2.0 - 1.0, d.y / D.tgt.y * 2.0 - 1.0, 0.0, 1.0); o.i = n;
  return o;
}
@fragment fn fsFoam(v: VO) -> @location(0) vec4f {
  let x = floor((v.p.x - D.m.z) / D.m.x); let y = floor((D.tgt.y - v.p.y - D.m.w) / D.m.y);
  let a = items[v.i * 2u]; let PB = D.wk[0].x; let c = a.x; let s = a.y; let t = a.w;
  var col = -1;
  if (a.z > 1.0) {
    let w = foamW(s); let nb = max(1.0, floor(w / PB + 0.5)); let bx = floor((c - w / 2.0) / PB) * PB; let sy = floor(surfRow(c) / PB) * PB;
    let i = floor((x - bx) / PB);
    if (i < 0.0 || i >= nb) { discard; }
    let u = (i + 0.5) / nb; let edge = 1.0 - abs(u * 2.0 - 1.0);
    let r = wLat(bitcast<i32>(items[v.i * 2u + 1u].x), i32(i), 31u);
    if (r < t * 0.9 - 0.05 * edge) { discard; }                     // (breaking up: pieces drop out, the ends first)
    let h = max(1.0, floor(foamHMax(nb, t) * (0.4 + 0.6 * edge) * (0.6 + 0.6 * r) + 0.5));
    if (y >= sy - h * PB + PB && y < sy + PB) { col = select(2, 0, t < 0.45); }
    else if (r > 0.6 && t < 0.7 && y >= sy + PB && y < sy + 2.0 * PB) { col = 3; }   // (the wet underside)
  } else {
    let wd = select(select(1.0, 2.0, s > 1.6), 3.0, s > 2.3);
    if (x >= c && x < c + wd && y == surfRow(c) - 1.0) { col = select(1, 0, t < 0.5); }
  }
  if (col < 0) { discard; }
  return D.wk[1 + col];
}
// ---- THE WHITE WATER (drawWclouds, 26-white-water.js): the billowing clouds of an underwater blast and the foam a surfacing sub throws off, layered as a pixel
// artist layers smoke - every cloud's dark base shape, then every cloud's smaller mid tone nudged toward the light, then lit ones, then a highlight. A blob a
// layer a cloud an instance, in that order (items: 2 each - its first cell's column and row in user space, its radius in cells, its alpha; its tone
// (premultiplied by nothing: 0..1), its seed); its lumpy outline worked out per cell on the smoke's grid (wk[0].x = SMK). Laid one over the next as the
// puffs' layer laid them (source-over is associative: the same as their layer laid on the view)
@vertex fn vsPuff(@builtin(vertex_index) v: u32, @builtin(instance_index) n: u32) -> VO {
  let a = items[n * 2u]; let K = D.wk[0].x; let N = (2.0 * a.z + 1.0) * K;
  let d = mix(a.xy, a.xy + vec2f(N), qd(v)) * D.m.xy + D.m.zw;
  var o: VO; o.p = vec4f(d.x / D.tgt.x * 2.0 - 1.0, d.y / D.tgt.y * 2.0 - 1.0, 0.0, 1.0); o.i = n;
  return o;
}
@fragment fn fsPuff(v: VO) -> @location(0) vec4f {
  let x = floor((v.p.x - D.m.z) / D.m.x); let y = floor((D.tgt.y - v.p.y - D.m.w) / D.m.y);
  let a = items[v.i * 2u]; let c = items[v.i * 2u + 1u]; let K = D.wk[0].x; let R = a.z;
  let dx = floor((x - a.x) / K) - R; let dy = floor((y - a.y) / K) - R;
