    var ed = 0.0; if (tl > t + 1.0) { ed = ceil(tl - t); } if (tr > t + 1.0) { ed = max(ed, ceil(tr - t)); }
    if (rf < floor(t) + ed) { return vec4f(rkp(pb + 5u), 1.0); }
