    if (sl < -0.6 && dy < 10.0) { k = 1; }
    if (u > 0.55) { k = select(3, 2, k == 1); }
    if (u > 0.8) { k = 4; }
    if ((r + i32(floor(f32(c) * 0.15))) % i32(B.x) == 0 && wLat(c, r, sd ^ 0x5bd1e995u) < 0.6) { k = 4; }   // (strata)
  }
