    let k = select(clamp(0.25 + 0.6 * nz * nz, 0.0, 0.85), 0.92, near < 2.0);
    let o = s * (1.0 - k) + (s * vec3f(0.15, 0.13, 0.12) + vec3f(12.0, 9.0, 8.0)) * k;
    return vec4f(o / 255.0 * c0.a, c0.a);
  }
