// the world's layer at a canvas pixel (its rows bottom first too)
fn worldAt(p: vec2f) -> vec4f {
  let d = vec2i(textureDimensions(world)); let x = i32(floor(p.x)); let y = i32(floor(p.y));
  if (x < 0 || y < 0 || x >= d.x || y >= d.y) { return vec4f(0.0); }
  return textureLoad(world, vec2i(x, d.y - 1 - y), 0);
}
// a shadows' mask at a canvas pixel (1: lit) - stretched over the target (its rows bottom first)
fn maskAt(t: texture_2d<f32>, p: vec2f) -> f32 {
  let d = vec2f(textureDimensions(t));
  let q = vec2i(clamp(p * d / P.tgt.xy, vec2f(0.0), d - 1.0));
  return textureLoad(t, vec2i(q.x, i32(d.y) - 1 - q.y), 0).r;
}
fn shadowAt(p: vec2f) -> f32 { return maskAt(shadowG, p) * maskAt(shadowC, p); }
// the fog layer at a canvas pixel (the world's layer's size, its rows bottom first; none: clear)
fn fogAt(p: vec2f) -> vec4f {
  let d = vec2i(textureDimensions(fogL)); let x = i32(floor(p.x)); let y = i32(floor(p.y));
  if (x < 0 || y < 0 || x >= d.x || y >= d.y) { return vec4f(0.0); }
  return textureLoad(fogL, vec2i(x, d.y - 1 - y), 0);
}
// the order layer at a canvas pixel: the number of the thing drawn there last (0: none - the sky, the ground, the water)
fn ordAt(p: vec2f) -> f32 {
  let d = vec2i(textureDimensions(ordL)); let x = i32(floor(p.x)); let y = i32(floor(p.y));
  if (x < 0 || y < 0 || x >= d.x || y >= d.y) { return 0.0; }
  let o = textureLoad(ordL, vec2i(x, d.y - 1 - y), 0);
  return round(o.r * 255.0) * 65536.0 + round(o.g * 255.0) * 256.0 + round(o.b * 255.0);
}
// THE LOW SUN ON THE LAKES' BOATS: its head in data from P.misc.w - 1 (lpassDuskHead): the boats' numbers (from, to - a pixel of theirs: from < n <= to),
// the sunset's strength, the lakes' count, the top row, the surface's columns, -, -; then each lake in view (DUSK_LAKE floats, in order across): its
// columns from, to (view px), its rows PY(level - 30), PY(level), PY(level + 60)
const DUSK_LAKE = 6u;
fn duskHead() -> i32 { return i32(P.misc.w) - 1; }
fn duskIn(od: f32) -> bool { let h = duskHead(); if (h < 0 || od <= 0.0) { return false; } return od > data[h] && od <= data[h + 1]; }
// the band at a canvas pixel, premultiplied - what the sea's band is at sea (renderObjects): over the column's surface (a row under it) from the top row
// the silhouette (29, 26, 61 at 0.9 x the sunset); in a lake's columns, from 30 over its level to 60 under it, the fade from 0.75 x the sunset at its
// level to nothing 60 under it, laid over that (two fills 'source-atop', as one)
fn duskAt(p: vec2f) -> vec4f {
  let h = u32(duskHead()); let q = p - P.misc.yz; let x = floor(q.x); let y = floor(q.y);
  let s = data[h + 2u]; let n = u32(data[h + 3u]); let top = data[h + 4u]; let nc = i32(data[h + 5u]);
  let col = vec3f(29.0, 26.0, 61.0);
  var o = vec4f(0.0);
  if (y + 0.5 > top && y < surfL[clamp(i32(x) + 3, 0, nc - 1)].x + 1.0) { o = pm(col, 0.9 * s); }
  let L = h + 8u;
  if (n > 0u && x >= data[L]) {
    var lo = 0u; var hi = n;
    for (var it = 0; it < 9; it++) { if (hi - lo <= 1u) { break; } let m = (lo + hi) / 2u; if (data[L + m * DUSK_LAKE] <= x) { lo = m; } else { hi = m; } }   // (at most LPASS.LAKES (256): 8 halvings)
    let b = L + lo * DUSK_LAKE;
    if (x < data[b + 1u] && y >= data[b + 2u] && y < data[b + 4u]) {
      let y0 = data[b + 3u]; let y1 = data[b + 4u];
      let t = clamp((y + 0.5 - y0) / (y1 - y0), 0.0, 1.0);
      o = over(pm(col, 0.75 * s * (1.0 - t)), o);
    }
  }
  return o;
}
// Math.round's (halves up - WGSL's round takes them to even)
fn jround(v: f32) -> f32 { return floor(v + 0.5); }
// premultiplied 'source-over': top laid over under
fn over(top: vec4f, under: vec4f) -> vec4f { return top + under * (1.0 - top.a); }
fn pm(rgb: vec3f, a: f32) -> vec4f { let k = clamp(a, 0.0, 1.0); return vec4f(rgb / 255.0 * k, k); }
// inside a rectangle (x, y, w, h - the canvas's, its corners rounded as fillRect's / drawImage's were)
fn inRect(p: vec2f, r: vec4f) -> bool { return p.x >= r.x && p.x < r.x + r.z && p.y >= r.y && p.y < r.y + r.w; }
// a canvas gradient between two stops (colours 0-255, alphas) at u: colour and alpha each mixed on their own, as the canvas does
// (a stop to rgba(0,0,0,0) falls as (1 - u)^2) - its light, premultiplied
fn gradPm(c0: vec3f, a0: f32, c1: vec3f, a1: f32, u: f32) -> vec3f { let t = clamp(u, 0.0, 1.0); return mix(c0, c1, t) / 255.0 * mix(a0, a1, t); }

@vertex fn vsFull(@builtin(vertex_index) i: u32) -> @builtin(position) vec4f { let x = f32((i << 1u) & 2u); let y = f32(i & 2u); return vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0); }
// 1. the dark: the world's layer at p as it goes to the screen - the hour's tint, the warm, the fog
fn darkAt(p: vec2f) -> vec4f { return darkOf(p, worldAt(p)); }
// a colour of the world's at p (premultiplied) as the dark lays it
fn darkOf(p: vec2f, c0: vec4f) -> vec4f {
  var c = c0;
  if (c.a <= 0.0) { return c; }
  if (P.band.w > 0.5) {
    var t = P.tint1;
    if (P.band.z > 0.5) { t = mix(P.tint0, P.tint1, clamp((p.y - P.band.x) / max(1e-3, P.band.y - P.band.x), 0.0, 1.0)); }
    c = vec4f(t.rgb * c.a + c.rgb * (1.0 - t.a), c.a);
  }
  if (P.warm.a > 0.0) { c = vec4f(P.warm.rgb * c.a + c.rgb * (1.0 - P.warm.a), c.a); }
  let f = fogAt(p); if (f.a > 0.0) { c = vec4f(f.rgb * c.a + c.rgb * (1.0 - f.a), c.a); }   // ('source-atop': only on what the world drew)
  return c;
}
@fragment fn fsDark(@builtin(position) pos: vec4f) -> @location(0) vec4f {
  let c = darkAt(canvasP(pos)); if (c.a <= 0.0) { discard; }
  return c;
}
// the world's layer copied as it is (the snapshot: the same pixel of a texture its size)
// the low sun on the lakes' boats (lightLakeDusk): the band on the pixels their drawing numbered, laid 'source-atop' into the world's layer
@fragment fn fsDusk(@builtin(position) pos: vec4f) -> @location(0) vec4f {
  let p = canvasP(pos);
  if (duskHead() < 0 || !duskIn(ordAt(p))) { discard; }
  let o = duskAt(p); if (o.a <= 0.0) { discard; }
  return o;
}
@fragment fn fsCopy(@builtin(position) pos: vec4f) -> @location(0) vec4f { return textureLoad(world, vec2i(pos.xy), 0); }
// cleared (a layer's view columns - the fog layer's, before its fog)
@fragment fn fsClear() -> @location(0) vec4f { return vec4f(0.0); }

// 2. the light table: one quad a row (two triangles), over its box
struct VO { @builtin(position) pos: vec4f, @location(0) @interpolate(flat) i: u32 };
@vertex fn vsRow(@builtin(vertex_index) v: u32, @builtin(instance_index) i: u32) -> VO {
  let B = rows[i].d;
  let kx = select(0.0, 1.0, v == 1u || v == 4u || v == 5u); let ky = select(0.0, 1.0, v == 2u || v == 3u || v == 5u);   // (two triangles: 0 1 2, 3 4 5)
  let X = mix(B.x, max(B.x, B.z), kx); let Y = mix(B.y, max(B.y, B.w), ky);
  var o: VO; o.pos = vec4f(2.0 * X / P.tgt.x - 1.0, 2.0 * Y / P.tgt.y - 1.0, 0.0, 1.0); o.i = i;
  return o;
}
fn beamFall(q: f32) -> f32 { if (q <= 0.0) { return 0.0; } return pow(q, 0.8) * smoothstep(0.0, 0.35, q); }
// a beam's light at d from its lamp along its aim u, reach L, its near fade n (px) - lampBeamAt (27-sub-light.js)
fn beam(d: vec2f, u: vec2f, L: f32, n: f32) -> f32 {
  let dd = length(d); if (dd >= L) { return 0.0; }
  let ca = select(dot(d, u) / dd, 1.0, dd < 0.5); let e0 = clamp((ca - 0.55) / 0.3, 0.0, 1.0); if (e0 <= 0.0) { return 0.0; }
  let core = clamp((ca - 0.8) / 0.18, 0.0, 1.0);
  return beamFall(1.0 - dd / L) * e0 * e0 * (3.0 - 2.0 * e0) * (0.55 + 0.45 * core) * (1.0 - exp(-dd / abs(n)));
}
// its own side of the water's row w: a lamp under the water (s > 0) lights under it, one above it above
fn wrongSide(p: vec2f, w: f32, s: f32) -> bool { let above = p.y < w; return select(!above, above, s > 0.0); }
// a glow's reach toward p (its rays, between the two nearest)
fn reachAt(o: u32, d: vec2f) -> f32 {
  var t = atan2(d.y, d.x); if (t < 0.0) { t = t + TAU; }
  let f = t / TAU * f32(RAYS) - 0.5; let fl = floor(f); let u = f - fl;
  let i0 = u32(i32(fl) + RAYS) % u32(RAYS); let i1 = (i0 + 1u) % u32(RAYS);
  return mix(reach[o + i0], reach[o + i1], u);
}
// a halo of stepped rings, 15 art pixels across (haloArt) drawn r round
fn haloA(p: vec2f, x: f32, y: f32, R: f32) -> f32 {
  let x0 = jround(x - R); let y0 = jround(y - R); let w = jround(R * 2.0);
  if (w < 1.0 || p.x < x0 || p.y < y0 || p.x >= x0 + w || p.y >= y0 + w) { return 0.0; }
  let c = floor((p - vec2f(x0, y0)) * 15.0 / w); let d = length(c - 7.0) / 7.5;
  return select(select(select(select(0.0, 0.07, d < 1.0), 0.2, d < 0.68), 0.5, d < 0.42), 1.0, d < 0.2);
}
// a big glow, N art pixels across (bigHaloArt), 2R wide: eight soft steps
fn bigHaloA(p: vec2f, x: f32, y: f32, R: f32, N: f32) -> f32 {
  let x0 = jround(x - R); let y0 = jround(y - R); let w = jround(R * 2.0);
  if (w < 1.0 || p.x < x0 || p.y < y0 || p.x >= x0 + w || p.y >= y0 + w) { return 0.0; }
  let c = floor((p - vec2f(x0, y0)) * N / w); let h = (N - 1.0) * 0.5; let d = length(c - h) / (h + 0.5);
  if (d >= 1.0) { return 0.0; }
  return jround(pow(1.0 - d, 1.8) * 8.0) / 8.0;
}
// a lighthouse's wedge: inside the triangle o, o + e1, o + e2
fn inTri(p: vec2f, o: vec2f, e1: vec2f, e2: vec2f) -> bool {
  let q = p - o; let d = e1.x * e2.y - e1.y * e2.x; if (abs(d) < 1e-6) { return false; }
  let s = (q.x * e2.y - q.y * e2.x) / d; let t = (e1.x * q.y - e1.y * q.x) / d;
  return s >= 0.0 && t >= 0.0 && s + t <= 1.0;
}
// the kinds drawn in the view's own px, in its blocks (PB) as the canvas drew them (q: the pixel in view px)
fn blockRow(y: f32, y0: f32, pb: f32) -> f32 { return y0 + floor((y - y0) / pb) * pb; }
fn ringW(r: f32, j: f32, pb: f32) -> f32 { let t = j + pb * 0.5; return floor(sqrt(max(0.0, r * r - t * t)) / pb) * pb; }
// inside a stepped disc of radius r (rows of PB, each its half width) round the block (bx, by)
fn inDisc(q: vec2f, bx: f32, by: f32, r: f32, pb: f32) -> bool {
  let j = floor((q.y - by) / pb) * pb; if (j < -r || j >= r) { return false; }
  let w = ringW(r, j, pb); return q.x >= bx - w && q.x < bx + w;
}
fn rowPx(R: Row, q: vec2f, kind: i32) -> vec4f {
  let col = R.b.rgb / 255.0; let pb = R.c.x;
  if (kind == 7) {        // softGlow: rings (a.w of them) of a.z round, each a / rings x (1.3 - 0.5 k / rings), added
    let n = R.a.w; var s = 0.0;
    for (var k = 1; k <= 18; k++) { if (f32(k) > n) { break; }
      let r = max(pb, jround(R.a.z * f32(k) / n / pb) * pb);
      if (inDisc(q, R.a.x, R.a.y, r, pb)) { s = s + R.b.w / n * (1.3 - 0.5 * f32(k) / n); } }
    return vec4f(col * s, 0.0);
  }
  if (kind == 8) {        // glowDisc: three rings (0.35, 0.35, 0.45 - added in its picture, which holds at most 1), the picture at a.w, added
    var s = 0.0;
    for (var k = 1; k <= 3; k++) { let r = max(pb, jround(R.a.z * f32(k) / 3.0 / pb) * pb);
      if (inDisc(q, R.a.x, R.a.y, r, pb)) { s = s + select(0.35, 0.45, k == 1); } }
    return vec4f(min(col * s, vec3f(1.0)) * R.a.w, 0.0);   // (its picture's bytes hold at most 1)
  }
  if (kind == 9) {        // a dock lamp's cone to its deck (a.z), the pool where it lands, its broken reflection on the water (c.z the top row)
    let px = R.a.x; let py = R.a.y; let dy = R.a.z; let sv = R.a.w; let LA = R.b.w; let fog = R.c.y; var s = 0.0;
    let y = blockRow(q.y, py + pb, pb);
    if (y >= py + pb && y < dy) { let u = (y - py) / (dy - py); let half = pb + u * 22.0 * sv;
      let x0 = floor((px - half) / pb) * pb; if (q.x >= x0 && q.x < x0 + ceil(half * 2.0 / pb) * pb) { s = s + (0.06 + 0.04 * fog) * LA * (1.0 - u * 0.4); } }
    for (var r = 0; r < 4; r++) { let w = (30.0 - f32(r) * 7.0) * sv; let x0 = floor((px - w) / pb) * pb; let y0 = dy - pb * f32(r + 1);
      if (q.y >= y0 && q.y < y0 + pb && q.x >= x0 && q.x < x0 + ceil(w * 2.0 / pb) * pb) { s = s + 0.05 * LA; } }
    for (var k = 0; k < 10; k++) { let off = jround(sin(P.misc.x * 2.0 + f32(k) * 1.7) * (2.0 + f32(k) * 0.4)); let len = (2.0 + f32(k % 3)) * pb;
      let x0 = floor((px + off * sv - len * 0.5) / pb) * pb; let y0 = floor((R.c.z + f32(k) * 4.5 * sv) / pb) * pb;
      if (q.y >= y0 && q.y < y0 + pb && q.x >= x0 && q.x < x0 + len) { s = s + 0.28 * LA * (1.0 - f32(k) / 11.0); } }
    return vec4f(col * s, 0.0);
  }
  if (kind == 11) {       // a bolt's glow: the cloud deck lit from under where it leaves it (a radial gradient), the sea under the strike (a band fading down)
    let vis = R.a.w; let gR = R.a.z; var o = vec4f(0.0);
    if (q.x >= R.a.x - gR && q.x < R.a.x + gR && q.y >= R.a.y - gR && q.y < R.a.y - gR + gR * 1.4) {
      let t = length(q - R.a.xy) / max(gR, 1e-3); let c0 = vec3f(150.0, 170.0, 230.0); let c1 = vec3f(90.0, 110.0, 180.0);
      o = vec4f(select(gradPm(c1, 0.25 * vis, vec3f(0.0), 0.0, (t - 0.45) / 0.55), gradPm(c0, 0.55 * vis, c1, 0.25 * vis, t / 0.45), t < 0.45), 0.0); }
    let S = R.b.z; let y0 = R.b.y - 6.0 * S;
    if (q.x >= R.b.x - jround(150.0 * S) && q.x < R.b.x - jround(150.0 * S) + jround(300.0 * S) && q.y >= y0 && q.y < y0 + 36.0 * S) {
      o = o + vec4f(gradPm(vec3f(120.0, 150.0, 230.0), 0.35 * vis, vec3f(0.0), 0.0, (q.y + 0.5 - y0) / (36.0 * S)), 0.0); }
    return o;
  }
  if (kind == 12) {       // the sea's broken light under a strike: a block a column (data: its row and strength - negative three blocks wide), added
    let x0 = R.a.x; let nc = i32(R.a.y); let off = u32(R.a.z); let i0 = i32(floor((floor(q.x / pb) * pb - x0) / pb + 0.5)); var s = 0.0;
    for (var j = 0; j < 3; j++) { let i = i0 - j; if (i < 0 || i >= nc) { continue; }
      let Y = data[off + u32(i) * 2u]; let a = data[off + u32(i) * 2u + 1u]; if (a == 0.0) { continue; }
      let w = select(pb, 3.0 * pb, a < 0.0); let X = x0 + f32(i) * pb;
      if (q.x >= X && q.x < X + w && q.y >= Y && q.y < Y + pb) { s = s + abs(a); } }
    return vec4f(vec3f(220.0, 232.0, 255.0) / 255.0 * s, 0.0);
  }
  if (kind == 13) {       // a bolt's line in blocks of c.x (blkLine): its points in data (x, y - a.y of them, at most 32), moved a.z across; laid over as often as a block is drawn
    let off = u32(R.a.x); let np = min(i32(R.a.y), 32); let bq = floor(q / pb) * pb; var cnt = 0.0;
    for (var k = 0; k < 31; k++) { if (k + 1 >= np) { break; }
      let A = vec2f(data[off + u32(k) * 2u] + R.a.z, data[off + u32(k) * 2u + 1u]); let B = vec2f(data[off + u32(k + 1) * 2u] + R.a.z, data[off + u32(k + 1) * 2u + 1u]);
      let n = max(1.0, ceil(length(B - A) / pb)); let d = B - A; let t = clamp(dot(bq + pb * 0.5 - A, d) / max(dot(d, d), 1e-6), 0.0, 1.0);
      let ic = jround(t * n);
      for (var m = -2; m <= 2; m++) { let i = ic + f32(m); if (i < 0.0 || i > n) { continue; }   // (a step is at most a block: those in it are within two of the nearest)
        if (all(floor((A + d * i / n) / pb) * pb == bq)) { cnt = cnt + 1.0; } } }
    if (cnt <= 0.0) { return vec4f(0.0); }
    return pm(R.b.rgb, 1.0 - pow(1.0 - R.b.w, cnt));
  }
  if (kind == 14) {       // the whole storm's flicker, strongest under the clouds (a.x, a.y: its gradient's rows), laid over
    let t = clamp((q.y + 0.5 - R.a.x) / max(1e-3, R.a.y - R.a.x), 0.0, 1.0);
    return pm(vec3f(214.0, 222.0, 255.0), R.a.z * mix(0.35, 1.0, t));
  }
  if (kind == 16) {       // a fog band: from row a.x (clear) to a.y (b.w) in b's colour, laid over - down to the water's surface (data a.z: its row every other
    // column from -3, a.w of them - surfaceLine's outline)
    if (q.y < R.a.x) { return vec4f(0.0); }
    let f = clamp((q.x + 3.0) * 0.5, 0.0, R.a.w - 1.0); let i = floor(f); let o = u32(R.a.z);
    let s = mix(data[o + u32(i)], data[o + u32(min(i + 1.0, R.a.w - 1.0))], f - i);
    if (q.y >= s) { return vec4f(0.0); }
    return pm(R.b.rgb, R.b.w * clamp((q.y - R.a.x) / max(1e-3, R.a.y - R.a.x), 0.0, 1.0));
  }
  if (kind == 17 || kind == 18) {   // the light on the water's skin, a column of a.y from a.x (a.w of them, data a.z: its surface row, how much each light lights
    // it - bytes: the moon's line, its glints x 256, the sun's glints x 65536): 17 the moon's line (b's colour) and glints over it (c's), 18 the sun's glints; b.w the line's rows
    let i = floor((q.x - R.a.x) / R.a.y); if (i < 0.0 || i >= R.a.w) { return vec4f(0.0); }
    let o = u32(R.a.z) + u32(i) * 2u; let y = data[o]; let k = u32(data[o + 1u]); let lw = R.b.w;
    if (kind == 17 && q.y >= y && q.y < y + lw) { return vec4f(col * f32(k & 255u) / 255.0, 0.0); }
    if (q.y >= y - lw && q.y < y) { return vec4f(R.c.rgb / 255.0 * f32((k >> select(8u, 16u, kind == 18)) & 255u) / 255.0, 0.0); }
    return vec4f(0.0);
  }
  if (kind == 19) {       // the grade's bloom round a bright light: a radial gradient (a.z round a.xy) from its warm at a.w to clear, added
    return vec4f(gradPm(vec3f(255.0, 214.0, 160.0), R.a.w, vec3f(255.0, 160.0, 90.0), 0.0, length(q - R.a.xy) / max(R.a.z, 1e-3)), 0.0);
  }
  if (kind == 22) {       // a soft glow (lightGlow): a canvas radial gradient round a.xy, a.z its radius, its stops in data from a.w - b.x of them (at most 4), each
    // its offset, colour (0-255) and alpha; colour and alpha each mixed on their own between two stops, as the canvas does - laid over
    let t = clamp(length(q - R.a.xy) / max(R.a.z, 1e-3), 0.0, 1.0); let o = u32(R.a.w); let n = min(u32(R.b.x), 4u);
